args.content:
.app-main {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  background: radial-gradient(circle, #2d3748 0%, #1a202c 100%);
  padding: 16px;
  box-sizing: border-box;
}

.calculator-container {
  width: 100%;
  max-width: 380px;
  background: #2d3748;
  border-radius: 20px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
  padding: 24px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.calculator-title {
  color: #fff;
  font-size: 1.4rem;
  font-weight: 600;
  text-align: center;
  margin: 0;
  letter-spacing: 0.5px;
}

/* Display styles */
.calculator-display {
  background: #1a202c;
  border-radius: 12px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
  box-sizing: border-box;
  min-height: 100px;
  justify-content: space-between;
}

.display-expression {
  color: #a0aec0;
  font-size: 1rem;
  word-break: break-all;
  min-height: 1.2rem;
  text-align: right;
  width: 100%;
}

.display-output {
  color: #fff;
  font-size: 2rem;
  font-weight: bold;
  word-break: break-all;
  min-height: 2.4rem;
  text-align: right;
  width: 100%;
}

.display-error {
  color: #fc8181;
  font-size: 1.1rem;
  font-weight: 500;
}

/* Button Grid styles */
.calculator-button-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.calc-btn {
  border: none;
  border-radius: 12px;
  padding: 16px;
  font-size: 1.2rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
  outline: none;
  box-sizing: border-box;
}

.calc-btn:active {
  transform: scale(0.95);
}

.calc-btn:focus-visible {
  outline: 3px solid #63b3ed;
  outline-offset: 1px;
}

/* Button types color mappings */
.btn-number {
  background: #4a5568;
  color: #fff;
}

.btn-number:hover {
  background: #718096;
}

.btn-operator {
  background: #ed8936;
  color: #fff;
}

.btn-operator:hover {
  background: #f6ad55;
}

.btn-action {
  background: #e2e8f0;
  color: #1a202c;
}

.btn-action:hover {
  background: #cbd5e0;
}

.btn-equals {
  background: #48bb78;
  color: #fff;
  grid-column: span 1;
}

.btn-equals:hover {
  background: #38a169;
}

/* Screen reader only utility class */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/* Mobile-first adjustments (widths down to 320px) */
@media (max-width: 350px) {
  .calculator-container {
    padding: 16px;
    gap: 12px;
  }

  .calc-btn {
    padding: 12px;
    font-size: 1.1rem;
  }

  .display-output {
    font-size: 1.6rem;
  }
}

